using System;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEditor;using UnityEngine;using UnityEngine.UI;using Rootborn.UI.Modern;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.StudentLife;using Rootborn.Game.Player;using Object=UnityEngine.Object;
namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanStudentStatusPanelTests{
GameObject root,owner,other;ModernUiStatusPanel panel;string language;GameDataRegistry registry;
[SetUp]public void Setup(){language=GameText.Language;registry=AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");GameDataRegistryProvider.SetOverrideForTests(registry);GameText.Language="ko";root=new GameObject("StatusFixture",typeof(RectTransform));panel=root.AddComponent<ModernUiStatusPanel>();owner=new GameObject("OwnedPlayer");other=new GameObject("OtherPlayer");}
[TearDown]public void Cleanup(){if(root!=null){panel.Hide();Object.DestroyImmediate(root);}Object.DestroyImmediate(owner);Object.DestroyImmediate(other);GameText.Language=language;GameDataRegistryProvider.ClearOverrideForTests();GameDataRegistryProvider.ResetCacheForTests();}
// EditMode does not dispatch regular MonoBehaviour enable/destroy callbacks; exercise the same producer/lifecycle callbacks explicitly.
StudentLifeProgressComponent Stats(GameObject go,int energy,int focus,int stress){var c=go.AddComponent<StudentLifeProgressComponent>();c.ConfigureForTests("fixture-status",go.name,energy,focus,stress,480);typeof(StudentLifeProgressComponent).GetMethod("OnEnable",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,null);return c;}
void Bind(GameObject go){var m=typeof(ModernUiStatusPanel).GetMethod("BindOwner",new[]{typeof(GameObject)});Assert.That(m,Is.Not.Null,"Status must bind only its explicitly selected inventory owner");m.Invoke(panel,new object[]{go});}
Text TextAt(string path){var t=root.transform.Find(path);Assert.That(t,Is.Not.Null,path);return t.GetComponent<Text>();}
[Test]public void MissingOwnerDoesNotBorrowOtherPlayersValues(){var b=Stats(other,11,9,1);var before=JsonUtility.ToJson(b.Progress.ToSaveData());Bind(null);panel.Show();Assert.That(TextAt("EnergyCard/Value").text,Is.EqualTo("--"));Assert.That(TextAt("FocusCard/Value").text,Is.EqualTo("--"));Assert.That(TextAt("StressCard/Value").text,Is.EqualTo("--"));Assert.That(JsonUtility.ToJson(b.Progress.ToSaveData()),Is.EqualTo(before));}
[TestCase("ko","나의 상태","체력","집중","스트레스")][TestCase("en","My status","Energy","Focus","Stress")]public void SelectedOwnerShowsLocalizedActualValuesWithoutWritingProgress(string lang,string title,string energy,string focus,string stress){GameText.Language=lang;var a=Stats(owner,7,5,3);Stats(other,11,9,1);var before=JsonUtility.ToJson(a.Progress.ToSaveData());Bind(owner);panel.Show();Assert.That(TextAt("StatusTitle").text,Is.EqualTo(title));Assert.That(TextAt("EnergyCard/Label").text,Is.EqualTo(energy));Assert.That(TextAt("FocusCard/Label").text,Is.EqualTo(focus));Assert.That(TextAt("StressCard/Label").text,Is.EqualTo(stress));Assert.That(TextAt("EnergyCard/Value").text,Is.EqualTo("7"));Assert.That(TextAt("FocusCard/Value").text,Is.EqualTo("5"));Assert.That(TextAt("StressCard/Value").text,Is.EqualTo("3"));string format=lang=="ko"?"{0}일차 · 남은 활동 {1}":"Day {0} · Activity points left: {1}";Assert.That(TextAt("DayPoints").text,Is.EqualTo(string.Format(format,a.Progress.CurrentDay,a.Progress.TimePointsRemaining)));Assert.That(JsonUtility.ToJson(a.Progress.ToSaveData()),Is.EqualTo(before));}
[Test]public void LateOwnedComponentAndVitalsEventsRefreshTheSameCards(){Bind(owner);panel.Show();Assert.That(TextAt("EnergyCard/Value").text,Is.EqualTo("--"));var a=Stats(owner,6,4,2);Assert.That(TextAt("EnergyCard/Value").text,Is.EqualTo("6"));a.ConfigureForTests("fixture-status",owner.name,8,3,1,500);Assert.That(TextAt("EnergyCard/Value").text,Is.EqualTo("8"));Assert.That(TextAt("FocusCard/Value").text,Is.EqualTo("3"));Assert.That(TextAt("StressCard/Value").text,Is.EqualTo("1"));}
[Test]public void RebindHideAndDestroyRemoveOldOwnedAndStaticSubscriptions(){var a=Stats(owner,7,5,3);var b=Stats(other,11,9,1);Bind(owner);panel.Show();Bind(other);a.ConfigureForTests("fixture-status",owner.name,2,2,2,480);Assert.That(TextAt("EnergyCard/Value").text,Is.EqualTo("11"));panel.Hide();foreach(string name in new[]{"TimeChanged","VitalsChanged"}){var action=(Action)typeof(StudentLifeProgressComponent).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(b);Assert.That(action==null||action.GetInvocationList().All(d=>!ReferenceEquals(d.Target,panel)),Is.True,name);}b.ConfigureForTests("fixture-status",other.name,9,4,2,500);panel.Show();Assert.That(TextAt("EnergyCard/Value").text,Is.EqualTo("9"));var saved=panel;typeof(ModernUiStatusPanel).GetMethod("OnDestroy",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(panel,null);Object.DestroyImmediate(root);root=null;var active=(Action)typeof(StudentLifeProgressComponent).GetField("AvailabilityChanged",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);Assert.That(active==null||active.GetInvocationList().All(d=>!ReferenceEquals(d.Target,saved)),Is.True);}
[Test]public void WeekendDayPointsComeFromAuthoredCalendarWithoutChangingData(){var a=Stats(owner,7,5,3);var data=a.Progress.ToSaveData();data.CurrentDay=20;data.TimePointsSpentToday=0;a.RestoreFromSaveData(data,null,null,null);Assert.That(a.Progress.TimePointsRemaining,Is.EqualTo(3),"Real authored day20 weekend budget");string before=JsonUtility.ToJson(a.Progress.ToSaveData());Bind(owner);panel.Show();Assert.That(TextAt("DayPoints").text,Is.EqualTo("20일차 · 남은 활동 3"));Assert.That(JsonUtility.ToJson(a.Progress.ToSaveData()),Is.EqualTo(before));}
[Test]public void WindowCardsLabelsAndCloseStayInsideMoldingWithoutFakePortraitOrHealth(){Stats(owner,7,5,3);Bind(owner);panel.Show();var rect=(RectTransform)root.transform;Assert.That(rect.rect.width,Is.GreaterThanOrEqualTo(560));Assert.That(rect.rect.height,Is.GreaterThanOrEqualTo(540));Assert.That(root.GetComponent<ModernUiTileImage>(),Is.Not.Null);Assert.That(root.transform.Find("PortraitFrame"),Is.Null);Assert.That(root.transform.Find("HealthGauge"),Is.Null);var inner=rect.rect;inner.xMin+=16;inner.xMax-=16;inner.yMin+=16;inner.yMax-=16;foreach(var text in root.GetComponentsInChildren<Text>()){var corners=new Vector3[4];text.rectTransform.GetWorldCorners(corners);foreach(var c in corners)Assert.That(inner.Contains(rect.InverseTransformPoint(c)),Is.True,text.name+" crosses window molding");}foreach(string name in new[]{"EnergyCard","FocusCard","StressCard"}){Assert.That(root.transform.Find(name).GetComponent<ModernUiTileImage>(),Is.Not.Null);Assert.That(root.transform.Find(name+"/Icon").GetComponent<UrbanUiIcon>(),Is.Not.Null);}root.transform.Find("StatusCloseButton").GetComponent<Button>().onClick.Invoke();Assert.That(panel.IsVisible,Is.False);}
[Test]public void LayoutReinstallWithoutNewOwnerPreservesTheExistingExplicitBinding(){Stats(owner,7,5,3);var inv=owner.AddComponent<PlayerInventory>();Stats(other,11,9,1);var canvas=new GameObject("ReinstallCanvas",typeof(RectTransform),typeof(Canvas));try{ModernUiPanelAutoInstaller.InstallOnCanvas(canvas.GetComponent<Canvas>(),inv);var status=canvas.GetComponentInChildren<ModernUiStatusPanel>(true);status.Show();Assert.That(status.transform.Find("EnergyCard/Value").GetComponent<Text>().text,Is.EqualTo("7"));ModernUiPanelAutoInstaller.InstallOnCanvas(canvas.GetComponent<Canvas>(),null);status.Show();Assert.That(status.transform.Find("EnergyCard/Value").GetComponent<Text>().text,Is.EqualTo("7"),"A later layout-only install must not erase an already selected inventory owner");}finally{foreach(var status in canvas.GetComponentsInChildren<ModernUiStatusPanel>(true))status.Hide();Object.DestroyImmediate(canvas);}}
[Test]public void InstallerBindsTheExplicitInventoryOwnerInsteadOfAnotherPlayer(){var a=Stats(owner,7,5,3);var inv=owner.AddComponent<PlayerInventory>();Stats(other,11,9,1);var canvas=new GameObject("OwnedCanvas",typeof(RectTransform),typeof(Canvas));try{ModernUiPanelAutoInstaller.InstallOnCanvas(canvas.GetComponent<Canvas>(),inv);var status=canvas.GetComponentInChildren<ModernUiStatusPanel>(true);status.Show();var value=status.transform.Find("EnergyCard/Value");Assert.That(value,Is.Not.Null);Assert.That(value.GetComponent<Text>().text,Is.EqualTo("7"));}finally{foreach(var status in canvas.GetComponentsInChildren<ModernUiStatusPanel>(true))status.Hide();Object.DestroyImmediate(canvas);}}
}}
